from __future__ import annotations

import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


_PRERELEASE_IDENTIFIER = (
    r"(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
)
_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-(" + _PRERELEASE_IDENTIFIER
    + r"(?:\." + _PRERELEASE_IDENTIFIER + r")*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise TypeError("version must be a string")

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    prerelease = match.group(4)
    build = match.group(5)
    return Version(
        major=int(match.group(1)),
        minor=int(match.group(2)),
        patch=int(match.group(3)),
        prerelease=tuple(prerelease.split(".")) if prerelease else (),
        build=tuple(build.split(".")) if build else (),
    )


def _coerce(version: str | Version) -> Version:
    if isinstance(version, Version):
        return version
    if isinstance(version, str):
        return parse(version)
    raise TypeError("version must be a string or Version")


def _sign(value: int) -> int:
    return (value > 0) - (value < 0)


def _is_numeric_identifier(identifier: str) -> bool:
    return bool(identifier) and identifier.isascii() and identifier.isdigit()


def _compare_versions(a: Version, b: Version) -> int:
    for left, right in (
        (a.major, b.major),
        (a.minor, b.minor),
        (a.patch, b.patch),
    ):
        if left != right:
            return _sign(left - right)

    if a.prerelease == b.prerelease:
        # Build metadata is ignored for precedence.
        return 0
    if not a.prerelease:
        return 1
    if not b.prerelease:
        return -1

    for left, right in zip(a.prerelease, b.prerelease):
        if left == right:
            continue

        left_numeric = _is_numeric_identifier(left)
        right_numeric = _is_numeric_identifier(right)
        if left_numeric and right_numeric:
            return _sign(int(left) - int(right))
        if left_numeric:
            return -1
        if right_numeric:
            return 1
        return _sign((left > right) - (left < right))

    return _sign(len(a.prerelease) - len(b.prerelease))


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare_versions(_coerce(a), _coerce(b))


@dataclass(frozen=True)
class _Comparator:
    operator: str
    version: Version


_OPERATORS = (">=", "<=", "^", "~", ">", "<", "=")


def _parse_comparator(token: str) -> _Comparator:
    for operator in _OPERATORS:
        if token.startswith(operator):
            version_text = token[len(operator):]
            if not version_text:
                break
            return _Comparator(operator, parse(version_text))
    else:
        return _Comparator("=", parse(token))

    raise ValueError(f"invalid comparator: {token!r}")


def _expand(comparator: _Comparator) -> tuple[_Comparator, ...]:
    operator = comparator.operator
    version = comparator.version

    if operator == "^":
        if version.major != 0:
            upper = Version(version.major + 1, 0, 0)
        elif version.minor != 0:
            upper = Version(0, version.minor + 1, 0)
        else:
            upper = Version(0, 0, version.patch + 1)
        return (
            _Comparator(">=", version),
            _Comparator("<", upper),
        )

    if operator == "~":
        upper = Version(version.major, version.minor + 1, 0)
        return (
            _Comparator(">=", version),
            _Comparator("<", upper),
        )

    return (comparator,)


def _parse_range(range_: str) -> tuple[tuple[_Comparator, ...], ...]:
    if not isinstance(range_, str):
        raise TypeError("range must be a string")

    text = range_.strip()
    if not text:
        raise ValueError("range must not be empty")

    comparator_sets = []
    for set_text in text.split("||"):
        set_text = set_text.strip()
        if not set_text:
            raise ValueError(f"invalid range: {range_!r}")

        tokens = set_text.split()
        if not tokens:
            raise ValueError(f"invalid range: {range_!r}")

        comparators = []
        for token in tokens:
            comparators.extend(_expand(_parse_comparator(token)))
        comparator_sets.append(tuple(comparators))

    return tuple(comparator_sets)


def _test_operator(operator: str, result: int) -> bool:
    if operator == "=":
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    if operator == "<=":
        return result <= 0
    raise ValueError(f"unknown operator: {operator!r}")


def _matches(version: Version, comparators: tuple[_Comparator, ...]) -> bool:
    if version.prerelease:
        allowed = any(
            comparator.version.prerelease
            and (
                comparator.version.major,
                comparator.version.minor,
                comparator.version.patch,
            )
            == (version.major, version.minor, version.patch)
            for comparator in comparators
        )
        if not allowed:
            return False

    return all(
        _test_operator(
            comparator.operator,
            _compare_versions(version, comparator.version),
        )
        for comparator in comparators
    )


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _coerce(version)
    return any(
        _matches(candidate, comparators)
        for comparators in _parse_range(range_)
    )

