import itertools
import random
import string
import sys

sys.path.insert(0, "/private/tmp/tmpu587mkse/pete/projects/devkit")

from devkit.semver import Version, compare, parse, satisfies

random.seed(20261027)

ALNUM_HYPHEN = string.ascii_letters + string.digits + "-"


def random_identifier():
    while True:
        ident = "".join(random.choice(ALNUM_HYPHEN) for _ in range(random.randint(1, 5)))
        if not (ident.isascii() and ident.isdigit() and len(ident) > 1 and ident[0] == "0"):
            return ident


def random_version():
    text = ".".join(str(random.randint(0, 12)) for _ in range(3))
    if random.random() < 0.5:
        text += "-" + ".".join(random_identifier() for _ in range(random.randint(1, 4)))
    if random.random() < 0.3:
        text += "+" + ".".join(random_identifier() for _ in range(random.randint(1, 3)))
    return text


versions = [random_version() for _ in range(400)]
for text in versions:
    assert str(parse(text)) == text, (text, str(parse(text)))

# comparator laws
for a in versions[:100]:
    assert compare(a, a) == 0
    for b in versions[:100]:
        ab = compare(a, b)
        ba = compare(b, a)
        assert ab in (-1, 0, 1)
        assert ab == -ba, (a, b, ab, ba)
        for c in versions[:20]:
            bc = compare(b, c)
            ac = compare(a, c)
            if ab <= 0 and bc <= 0:
                assert ac <= 0, (a, b, c, ab, bc, ac)
            if ab >= 0 and bc >= 0:
                assert ac >= 0, (a, b, c, ab, bc, ac)

# build metadata never affects compare or satisfies
for text in versions[:100]:
    v = parse(text)
    withbuild = Version(v.major, v.minor, v.patch, v.prerelease, ("x", "1"))
    assert compare(v, withbuild) == 0
    assert satisfies(withbuild, f"={text}")

# Range: expansion bound checks. For each caret/tilde case, randomly probe.
for _ in range(1000):
    parts = [random.randint(0, 4) for _ in range(3)]
    base = Version(*parts)
    lower = str(base)
    for op in ("^", "~"):
        rng = op + lower
        assert satisfies(base, rng)
        if op == "^":
            if parts[0]:
                below = Version(parts[0] + 1, 0, 0)
            elif parts[1]:
                below = Version(0, parts[1] + 1, 0)
            else:
                below = Version(0, 0, parts[2] + 1)
        else:
            below = Version(parts[0], parts[1] + 1, 0)
        assert not satisfies(below, rng), (lower, rng, below)
        if parts[2] > 0:
            just_below = Version(parts[0], parts[1], parts[2] - 1)
            assert not satisfies(just_below, rng)

print("fuzz/property tests passed")

